import type { Plugin } from "vite";

export function buildOnly(plugin: Plugin | { name: string }): Plugin {
  let serve = false;

  const record = plugin as Record<string, unknown>;
  const wrapped: Record<string, unknown> = { name: record.name };

  for (const key of Object.keys(record)) {
    if (key === "name") continue;
    const value = record[key];
    if (typeof value !== "function") {
      wrapped[key] = value;
      continue;
    }
    wrapped[key] = function (this: unknown, ...args: unknown[]) {
      if (serve) return;
      return value.apply(this, args);
    };
  }

  const innerConfigResolved = wrapped.configResolved as
    | ((...args: unknown[]) => unknown)
    | undefined;
  wrapped.configResolved = function (
    this: unknown,
    config: { command: string },
  ) {
    serve = config.command === "serve";
    if (!serve && innerConfigResolved) {
      return innerConfigResolved.call(this, config);
    }
  };

  return wrapped as unknown as Plugin;
}
